"""SPIRIT.md: the project's reasons next to the passages, for people to read."""
from __future__ import annotations

from . import align as A


def render(reqs, ledger: dict) -> str:
    out = ["# Why this project does what it does, read next to its texts", "",
           "Generated by `specdeck spirit report` from `requirements.yaml` and `spirit.yaml`. A local open model proposed "
           "these connections and the people on the project decide what to keep. The quotes are the text's own words. "
           "They're one reader's connections, not what any tradition teaches.", ""]
    statements = {r.id: " ".join(r.statement.split()) for r in reqs.items.values()}
    for book in ledger["texts"].values():
        entries = book.get("entries") or {}
        with_passage = [e for e in entries.values() if e.get("ref") and e.get("status") != "rejected"]
        out += [f"## {book['title']} ({book['tradition']})", "",
                f"Translation is {book.get('translation') or 'not stated'}. "
                f"{len(with_passage)} of {len(entries)} reasons have a passage.", ""]
        if book.get("reflection"):
            out += [book["reflection"], ""]
        for rid, e in entries.items():
            if e.get("status") == "rejected":
                continue
            out += [f"### {'The purpose of the project' if rid == A.PURPOSE_ID else rid}", ""]
            if rid in statements:
                out += [statements[rid], ""]
            out += [f"Why. {e['why']}", ""]
            if e.get("ref"):
                out += ["> " + " ".join(e["quote"].split()), "", f"{e['ref']}, {e['relation']}, {e['status']}.", ""]
                if e.get("how"):
                    out += [e["how"], ""]
            else:
                out += ["No passage fits this reason, and that's allowed.", ""]
        if book.get("reading"):
            out += ["### Further reading", ""]
            out += [f"- {r['read']}. {r['why']}" for r in book["reading"]]
            out.append("")
    return "\n".join(out)
